<?php require __DIR__.'/../config/db.php';require __DIR__.'/../includes/functions.php';require_admin();$event=active_event($pdo);if(!$event){flash('error','กรุณาสร้างและเปิดใช้งานงานก่อน');header('Location: events.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$time=trim($_POST['slot_time']??'');$title=trim($_POST['title']??'');$location=trim($_POST['location']??'');if($time&&$title){$v=[$time,$title,$location?:null,(int)($_POST['sort_order']??0)];if($id){$q='UPDATE time_slots SET slot_time=?,title=?,location=?,sort_order=? WHERE id=? AND event_id=?';$v[]=$id;$v[]=$event['id'];}else{$q='INSERT INTO time_slots(slot_time,title,location,sort_order,event_id) VALUES(?,?,?,?,?)';$v[]=$event['id'];}$pdo->prepare($q)->execute($v);flash('success','บันทึกช่วงเวลาเรียบร้อย');}}elseif($action==='delete'&&($id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT))){$pdo->prepare('DELETE FROM time_slots WHERE id=? AND event_id=?')->execute([$id,$event['id']]);flash('success','ลบช่วงเวลาเรียบร้อย');}header('Location: time_slots.php');exit;}$edit=null;if($id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)){$q=$pdo->prepare('SELECT * FROM time_slots WHERE id=? AND event_id=?');$q->execute([$id,$event['id']]);$edit=$q->fetch();}$q=$pdo->prepare('SELECT * FROM time_slots WHERE event_id=? ORDER BY sort_order,id');$q->execute([$event['id']]);$rows=$q->fetchAll();$adminTitle='ตารางเวลา';$adminPage='slots';require __DIR__.'/header.php'; ?>
<div class="admin-panel"><h2><?= $edit?'แก้ไขช่วงเวลา':'เพิ่มช่วงเวลากิจกรรม'?> · <?=e($event['name'])?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="field-grid"><div class="field"><label class="field-label">เวลา</label><input class="input" name="slot_time" required value="<?=e($edit['slot_time']??'')?>" placeholder="06.30"></div><div class="field"><label class="field-label">ลำดับ</label><input class="input" type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></div><div class="field span-full"><label class="field-label">ชื่อกิจกรรม</label><input class="input" name="title" required value="<?=e($edit['title']??'')?>"></div><div class="field span-full"><label class="field-label">สถานที่</label><input class="input" name="location" value="<?=e($edit['location']??'')?>"></div></div><div class="actions"><button class="button button-primary">บันทึก</button><?php if($edit):?><a class="button button-outline" href="time_slots.php">ยกเลิก</a><?php endif;?></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>เวลา</th><th>กิจกรรม</th><th>สถานที่</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['slot_time'])?></td><td><?=e($r['title'])?></td><td><?=e($r['location'])?></td><td><div class="inline-form"><a class="button button-outline button-small" href="?edit=<?=$r['id']?>">แก้ไข</a><form method="post" onsubmit="return confirm('ลบช่วงเวลานี้หรือไม่?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-danger button-small">ลบ</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/footer.php';
